import 'package:flutter/material.dart';
import 'package:audioplayers/audioplayers.dart';
class HomeScreen extends StatefulWidget {
  const HomeScreen({super.key});

  @override
  State<HomeScreen> createState() => _HomeScreenState();
}

class _HomeScreenState extends State<HomeScreen> {
  final player = AudioPlayer();
  bool isPlay = false;
  bool isFirstTime = true;
 
  Duration duration=Duration.zero;
  Duration position=Duration.zero;
  
  
  @override
  void initState() {
    // بتتنفذ ع بدايه كل STATE
    // يعني كل حاجه هنا هتتنفذ هيتنفذ قصادها الinitState 
    super.initState();
    player.onPlayerStateChanged.listen((listenState){
       setState(() {
      isPlay=listenState==PlayerState.playing;
    });
      
    });
   
    player.onDurationChanged.listen((dur){
      setState(() {
        
        duration=dur;
      });
    });
    player.onPositionChanged.listen((pos){
      setState(() {
        position=pos;
      });
    });
  }
  @override
  
  Widget build(BuildContext context) {
  
    return Scaffold(
      body: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Container(
            width: 300,
            height: 250,
            decoration: BoxDecoration(
             
              borderRadius: BorderRadius.circular(20),
              image: const DecorationImage(image:NetworkImage("data:image/jpeg;base64,"))
            ),
          ),
          Slider( 
            min: 0,
            max: duration.inSeconds.toDouble(),
            value: position.inSeconds.toDouble(),
            onChanged: (val){
            player.seek(Duration(seconds:val.toInt() ));
             }),

           Row(mainAxisAlignment: MainAxisAlignment.spaceAround,
             children: [
              Text("$position"),
              
               InkWell(
                onTap: (){
                setState(() {
                  isPlay =! isPlay;
                });

                },
                 child: CircleAvatar(
                  radius: 40,
                  backgroundColor: Colors.blue,
                  child: isPlay? const Icon(Icons.pause,size: 50,):
                  const Icon(Icons.play_arrow,size: 50,),
                 ),
               ),
             
               Text("$duration")
             ],
           ),

        ],
      ),
      
      
      
      
      
      
      );}
      
      
      
      
      }